head.b:skin:
/* ============================================================
   Fonts, inlined.

   Both families are variable fonts, so one file per subset covers
   every weight this theme uses: Space Grotesk 400-700 (headings,
   nav, buttons) and Source Serif 4 400-600 (body). The browser
   downloads a subset only if a glyph in it is actually rendered,
   so an English page pulls the two "latin" files and nothing else.

   font-display:swap paints the fallback immediately and swaps the
   webfont in, which is what keeps FCP off the critical path.
   ============================================================ */
@font-face{
  font-family:'Source Serif 4';font-style:normal;font-weight:400 600;font-display:swap;
  src:url(https://fonts.gstatic.com/s/sourceserif4/v14/vEFI2_tTDB4M7-auWDN0ahZJW1gb8tc.woff2) format('woff2');
  unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;
}
@font-face{
  font-family:'Source Serif 4';font-style:normal;font-weight:400 600;font-display:swap;
  src:url(https://fonts.gstatic.com/s/sourceserif4/v14/vEFI2_tTDB4M7-auWDN0ahZJW1gV8tenXg.woff2) format('woff2');
  unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF;
}
@font-face{
  font-family:'Space Grotesk';font-style:normal;font-weight:400 700;font-display:swap;
  src:url(https://fonts.gstatic.com/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPbF4Cw.woff2) format('woff2');
  unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;
}
@font-face{
  font-family:'Space Grotesk';font-style:normal;font-weight:400 700;font-display:swap;
  src:url(https://fonts.gstatic.com/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPb94C-s0.woff2) format('woff2');
  unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF;
}

/* Metric-adjusted fallbacks. font-display:swap means the page first paints in
   the fallback and then re-lays out in the webfont; without these two faces
   that swap moves every line of text (CLS). size-adjust scales the fallback to
   the webfont's average glyph width so the reflow is a couple of pixels, not a
   paragraph. */
@font-face{
  font-family:'Space Grotesk Fallback';src:local('Arial'),local('Helvetica');
  size-adjust:104%;ascent-override:90%;descent-override:22%;line-gap-override:0%;
}
@font-face{
  font-family:'Source Serif 4 Fallback';src:local('Georgia'),local('Times New Roman');
  size-adjust:101%;ascent-override:94%;descent-override:26%;line-gap-override:0%;
}

:root{
  --bg:#F7F8FA; --surface:#FFFFFF; --ink:#1B1F27; --ink-soft:#5B6270;
  --line:#E4E7EC; --accent:#1F6F5C; --accent-ink:#0F4A3C; --gold:#C77D2E;
  --max:1160px;
  --font-head:'Space Grotesk','Space Grotesk Fallback',system-ui,sans-serif;
  --font-body:'Source Serif 4','Source Serif 4 Fallback',Georgia,serif;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0;background:var(--bg);color:var(--ink);
  font-family:var(--font-body);font-size:17px;line-height:1.65}
a{color:inherit;text-decoration:none}
img{max-width:100%;height:auto;display:block}
.container{width:min(var(--max),calc(100% - 32px));margin:auto}

/* Keyboard: every interactive element gets a visible ring. Blogger's own
   outline:0 on the search field is overridden below. */
a:focus-visible,button:focus-visible,input:focus-visible,
summary:focus-visible,[tabindex]:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.nav a:focus-visible,.footer a:focus-visible{outline-color:#FFD98A}
.skip-link{position:absolute;left:8px;top:-100px;z-index:200;background:var(--accent);color:#fff;
  font-family:var(--font-head);font-size:14px;font-weight:600;padding:12px 18px;border-radius:0 0 6px 6px;
  transition:top .12s ease}
.skip-link:focus{top:0}

.header{background:var(--surface);border-bottom:1px solid var(--line)}
/* Brand in the LEFT corner of the bar, social icons in the RIGHT corner,
   always on the same line. This used to be a flex row with flex-wrap:wrap:
   the moment the title + tagline were wider than the space left beside them
   - any phone, or desktop with a long blog description - the icons wrapped
   onto a second line, and a wrapped line holds only one item, so
   justify-content:space-between left-aligned it. Result: the icons sat
   *under* "Free Stack Hub" instead of opposite it. A two-column grid has no
   wrap to fall back on, so the icons stay pinned to the right edge and the
   brand column absorbs the squeeze (minmax(0,1fr) + overflow-wrap).

   align-items:start: BOTH columns hug the top edge of the bar together.
   The icons were moved to the top first (align-self:start) while the grid
   still centred the brand, so the wordmark floated at the bar's vertical
   middle, misaligned against the icons. Same top edge for both is the
   clean version; the content is ~50px + padding, so the bar's leftover
   slack sits below both equally. If the two ever cannot share the top
   edge, the fallback is to centre BOTH again - never one top, one middle. */
.brand-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:start;
  min-height:100px;padding:18px 0;column-gap:24px}
.brand{display:block;min-width:0}
.brand-title{font-family:var(--font-head);font-size:26px;font-weight:700;letter-spacing:-0.01em;
  line-height:1.2;overflow-wrap:break-word}
.brand-title span{color:var(--accent)}
.brand-tagline{font-size:12.5px;color:var(--ink-soft);margin-top:3px;overflow-wrap:break-word}
/* no align-self override: the grid's align-items:start pins this row to
   the TOP of the bar, same edge as the wordmark it sits opposite. */
.social-row{display:flex;align-items:center;justify-content:flex-end;gap:6px}
/* A 34px round hit area around a 19px glyph: the bare icon was an 18px tap
   target, which is what the mobile Accessibility audit reports as "tap
   targets are not sized appropriately". */
.social-row a{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;
  border-radius:50%;color:var(--ink-soft);transition:background-color .16s ease,color .16s ease}
.social-row a:hover,.social-row a:focus-visible{color:var(--accent-ink);background:#E4F1ED}
.social-row svg{width:19px;height:19px}

.nav-wrap{background:var(--ink)}
.nav{min-height:46px;display:flex;align-items:center;gap:0;overflow-x:auto;white-space:nowrap}
.nav a{padding:13px 16px;font-family:var(--font-head);font-size:13.5px;font-weight:500;color:#EDEFF2;border-right:1px solid rgba(255,255,255,.08)}
.nav a:hover{background:var(--accent);color:#fff}

/* ============================================================
   Search bar - a COMBO BOX, and it sits ABOVE the navbar (the body
   puts .search-wrap before the nav element).

   In the markup the field is still a plain Blogger search form: with
   JavaScript off - or in the moment before the index arrives - Enter
   submits it to /search?q= exactly as before. The script at the end
   of <body> fills the <ul class='suggest'> under the field and
   narrows that list on every keystroke, word by word.

   The panel is absolutely positioned inside .search-field and only
   ever toggles `display`, so opening it pushes nothing down: the
   navbar, the visitor strip and the cards stay exactly where they
   were (CLS 0). It overlaps the page instead of adding height to it.
   ============================================================ */
.search-wrap{position:relative;z-index:60;padding:14px 0;background:var(--surface);
  border-bottom:1px solid var(--line)}
.search{display:flex;align-items:stretch;max-width:640px;margin:auto}
.search-field{position:relative;display:flex;flex:1;min-width:0}
.search input{flex:1;min-width:0;border:1px solid var(--line);border-right:0;padding:11px 13px;
  font-family:var(--font-body);font-size:15px;color:var(--ink);background:var(--surface);
  border-radius:6px 0 0 6px}
.search input:focus{outline:3px solid var(--accent);outline-offset:-3px}
.search input::placeholder{color:#4A5160;opacity:1}
.search button{border:1px solid var(--accent);background:var(--accent);color:#fff;padding:0 18px;cursor:pointer;font-family:var(--font-head);font-weight:600;font-size:13px;border-radius:0 6px 6px 0}
.search button:hover{background:var(--accent-ink);border-color:var(--accent-ink)}

/* the drop-down list itself. Rows are built by the script: a title with
   the typed words wrapped in <mark>, then a small uppercase meta line
   (the post's labels, or "Category" / "Every result"). */
.suggest{position:absolute;top:calc(100% + 6px);left:0;right:0;z-index:70;display:none;
  list-style:none;margin:0;padding:6px;background:var(--surface);border:1px solid var(--line);
  border-radius:10px;box-shadow:0 18px 38px rgba(16,24,40,.16);
  max-height:min(58vh,340px);overflow-y:auto;overscroll-behavior:contain}
.suggest.is-open{display:block}
.suggest li{margin:0;padding:0;border:0;font-size:14px}
.suggest a{display:flex;flex-direction:column;gap:2px;padding:9px 11px;border-radius:7px;
  color:var(--ink);line-height:1.35}
.suggest a:hover{background:#EAF3F0}
/* the keyboard row: same tint as hover, plus a 3px accent bar on the left
   so "where am I in the list" is obvious without a mouse. */
.suggest li.is-active>a{background:#EAF3F0;color:var(--ink);box-shadow:inset 3px 0 0 var(--accent)}
.sg-title{font-family:var(--font-head);font-size:14px;font-weight:600;overflow-wrap:anywhere}
.sg-title mark{background:none;color:var(--accent-ink);font-weight:700}
.sg-meta{font-family:var(--font-head);font-size:11px;letter-spacing:.04em;color:var(--ink-soft);
  text-transform:uppercase}
.suggest .sg-label .sg-title{color:var(--accent-ink)}
.suggest .sg-all a{margin-top:4px;border-top:1px solid var(--line);border-radius:0 0 7px 7px;
  color:var(--accent-ink);font-family:var(--font-head);font-weight:600}
@media(max-width:560px){
  .search-wrap{padding:12px 0}
  .search button{padding:0 14px}
  .suggest{max-height:min(52vh,300px);box-shadow:0 12px 26px rgba(16,24,40,.18)}
}

.ad-slot{margin:20px 0}
.ad-slot .ad-inner{border:1px dashed var(--line);background:var(--surface);text-align:center;padding:12px}
.ad-slot .ad-label{font-family:var(--font-head);font-size:10px;letter-spacing:.08em;color:var(--ink-soft);text-transform:uppercase;margin-bottom:6px}

.main-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:34px;padding:28px 0}
.content-area{min-width:0}

.post-outer{background:var(--surface);border:1px solid var(--line);padding:22px 24px;margin:0 0 20px}
.post-title{font-family:var(--font-head);font-size:24px;line-height:1.3;margin:0 0 8px;font-weight:600}
.post-title a:hover{color:var(--accent)}
.post-meta,.post-timestamp{font-size:12.5px;color:var(--ink-soft)}
.post-header{border-bottom:1px solid var(--line);padding-bottom:12px;margin-bottom:14px}
.post-body{font-size:16.5px}
.post-body pre{background:#12161C;color:#E7E9EE;padding:13px;overflow:auto;font-size:13.5px}
.post-labels{margin-top:14px}
.post-labels a:hover{background:var(--accent);color:#fff}
.post-footer{margin-top:14px;padding-top:12px;border-top:1px solid var(--line);font-size:12.5px;color:var(--ink-soft)}

.download-box{margin:20px 0;padding:16px 18px;border:1px solid var(--accent);background:#F0F6F4}
.download-box strong{display:block;font-family:var(--font-head);font-size:15px;margin-bottom:4px}
.download-box .meta{font-size:13px;color:var(--ink-soft);margin-bottom:10px}
.download-box a.dl-btn{display:inline-block;background:var(--accent);color:#fff;font-family:var(--font-head);font-weight:600;font-size:13.5px;padding:9px 18px}
.download-box a.dl-btn:hover{background:var(--accent-ink)}

.sidebar{min-width:0}
.widget{background:var(--surface);border:1px solid var(--line);margin-bottom:20px}
.widget h2,.widget h3{font-family:var(--font-head);font-size:12.5px;letter-spacing:.05em;text-transform:uppercase;color:var(--ink-soft);margin:0;padding:13px 15px;border-bottom:1px solid var(--line)}
.widget-content{padding:12px 15px 15px}
.sidebar ul{list-style:none;margin:0;padding:0}
.sidebar li{border-bottom:1px solid var(--line);padding:8px 0;font-size:13.5px}
.sidebar li:last-child{border-bottom:none}
.sidebar a:hover{color:var(--accent)}

.footer{border-top:1px solid var(--line);background:var(--ink);color:#C7CBD3;padding:28px 0 18px;margin-top:10px}
.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:26px}
.footer h3{font-family:var(--font-head);font-size:13px;text-transform:uppercase;letter-spacing:.05em;color:#fff;margin-top:0}
.footer p,.footer li{font-size:13px;color:#B7BCC6}
.footer ul{list-style:none;padding:0;margin:0}
.footer li{padding:4px 0}
.footer a:hover{color:var(--gold)}
.copyright{border-top:1px solid rgba(255,255,255,.1);margin-top:20px;padding-top:14px;text-align:center;font-size:12px;color:#A8B0BE}

.blog-pager{display:flex;justify-content:center;gap:10px;margin:16px 0 6px}
.blog-pager a{border:1px solid var(--line);background:var(--surface);padding:8px 14px;font-family:var(--font-head);font-size:13px}
.blog-pager a:hover{border-color:var(--accent);color:var(--accent)}
.feed-links{display:none}
.post-share-buttons,.post-share-buttons-bottom,.share-buttons,.PostShare,.gs-c-share{display:none !important}

@media(max-width:860px){
  .main-layout{grid-template-columns:1fr;gap:14px}
  .footer-grid{grid-template-columns:1fr}
}
@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{transition-duration:.001ms !important;animation-duration:.001ms !important;
    animation-iteration-count:1 !important;scroll-behavior:auto !important}
}
@media(max-width:560px){
  /* Still one line, still two corners - just tighter, so the icons never
     crowd the wordmark. Nothing here re-wraps the header. */
  .brand-row{min-height:76px;padding:12px 0;column-gap:10px}
  .brand-title{font-size:20px}
  .brand-tagline{font-size:11.5px}
  .social-row{gap:0}
  .social-row a{width:31px;height:31px}
  .social-row svg{width:17px;height:17px}
  .post-title{font-size:20px}
  .post-outer{padding:18px}
}

/* ============================================================
   List cards (home / label / search / archive).
   Each card is the feature image full width across the top,
   then the labels, the title, the date and a Read More button
   that opens that post's own URL. Deliberately NO body text:
   the cards used to print data:post.snippets.long, which is
   roughly the first 1000 characters of the post, so the home
   page read like a wall of the post itself.
   ============================================================ */
.post-list{display:flex;flex-direction:column;gap:24px}
.post-card{background:var(--surface);border:1px solid var(--line);border-radius:12px;overflow:hidden;
  transition:border-color .16s ease, box-shadow .16s ease}
.post-card:hover{border-color:#CFD6E0;box-shadow:0 12px 28px rgba(16,24,40,.08)}
/* The image gets a fixed 16:9 box, filled with object-fit:cover. The old
   side-column version stretched the image to the card's full height on wide
   screens (min-height:100% + height:100%), which cropped away most of it -
   that is why post images looked broken on PC. */
.card-media{display:block;background:#EAEEF3;aspect-ratio:16/9;overflow:hidden}
.card-media img{width:100%;height:100%;object-fit:cover}
/* Blogger renders Label thumbnails with markup this theme does not control;
   pinning a square box means they cannot push the column down. */
.sidebar .widget img{aspect-ratio:1/1;height:auto;object-fit:cover}
.card-body{padding:20px 22px;min-width:0;display:flex;flex-direction:column;align-items:flex-start}
.card-tags{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 10px}
.card-tags a{font-family:var(--font-head);font-size:10.5px;font-weight:600;letter-spacing:.07em;
  text-transform:uppercase;color:var(--accent);background:#EAF3F0;padding:4px 9px;border-radius:4px}
.card-tags a:hover{background:var(--accent);color:#fff}
.card-title{font-family:var(--font-head);font-size:22px;line-height:1.28;font-weight:600;margin:0 0 8px}
.card-title a:hover{color:var(--accent)}
.card-meta{font-size:12.5px;color:var(--ink-soft);margin:0 0 12px}
.card-more{margin-top:14px}
.read-more{display:inline-flex;align-items:center;gap:9px;background:var(--accent);color:#fff;
  font-family:var(--font-head);font-size:13.5px;font-weight:600;padding:10px 18px;border-radius:6px}
.read-more:hover{background:var(--accent-ink);color:#fff}
.read-more span{transition:transform .16s ease}
.read-more:hover span{transform:translateX(3px)}
.post-meta .post-author{color:var(--ink-soft)}

/* ============================================================
   "Most Viewed Stories" (PopularPosts) sidebar widget.
   It used to be titled "Most Downloaded", which described a
   download counter this blog does not have - Blogger's
   PopularPosts ranks by PAGE VIEWS, so the heading now says what
   the list actually is. Blogger's default markup also prints a
   long snippet under every entry, which turned the sidebar into
   dozens of lines per post; the widget renders the custom
   includable below instead: a small thumbnail plus the title.
   ============================================================ */
.popular-list{list-style:none;margin:0;padding:0}
.popular-list li{border-bottom:1px solid var(--line);padding:9px 0}
.popular-list li:first-child{padding-top:2px}
.popular-list li:last-child{border-bottom:none;padding-bottom:0}
.sidebar .popular-list a{display:flex;gap:12px;align-items:center;font-family:var(--font-head);
  font-size:14px;font-weight:600;line-height:1.4;color:var(--ink)}
.sidebar .popular-list a:hover{color:var(--accent)}
/* object-fit:contain (not cover): the whole thumbnail stays visible inside
   the 56px box, letterboxed on the grey ground - nothing is cropped. */
.sidebar .popular-list img{width:56px;height:56px;flex:none;object-fit:contain;border-radius:6px;
  background:#EAEEF3}

/* labels + comment link on the post page itself */
.post-labels a{display:inline-block;font-family:var(--font-head);font-size:11px;font-weight:600;
  letter-spacing:.06em;text-transform:uppercase;color:var(--accent);border:1px solid #D6E4E0;
  background:#F1F7F5;padding:4px 9px;margin:0 6px 6px 0;border-radius:4px}
.post-labels a:hover{background:var(--accent);border-color:var(--accent);color:#fff}
.comment-link{display:inline-block;margin-top:6px;font-family:var(--font-head);font-size:13px;
  font-weight:600;color:var(--accent)}
.comment-link:hover{color:var(--accent-ink)}

/* ============================================================
   Live visitor strip - markup goes out ONLY on the home page
   (the b:if on data:view.isHomepage in the body).

   Weight budget, because PageSpeed: every icon is inline SVG in
   currentColor (no icon font, no image), the country flag is an
   emoji built in JS (no flag sprite), the clock is one text update
   per second, and both data calls are ~300-byte JSON GETs fired
   after load during browser idle time. The skin reserves the whole
   strip up front (min-height on .visit-strip, fixed cell padding),
   so a number swapping an em dash in never shifts layout.

   Animations stay in the two cheapest properties, transform and
   opacity, and there are exactly two of them: a one-shot rise on
   entry and a 2px live-dot pulse. The global prefers-reduced-motion
   block above already collapses both; the JS also skips its count-up
   under reduced motion.
   ============================================================ */
.visit-wrap{padding-top:16px}
.visit-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;
  background:var(--line);border:1px solid var(--line);border-radius:10px;overflow:hidden;
  min-height:56px;animation:visitIn .5s ease-out both}
@keyframes visitIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.visit-cell{display:flex;align-items:center;gap:10px;background:var(--surface);
  padding:10px 14px;min-width:0}
.visit-icon{flex:none;width:30px;height:30px;display:inline-flex;align-items:center;
  justify-content:center;position:relative;color:var(--accent);background:#EAF3F0;border-radius:50%}
.visit-icon svg{width:16px;height:16px}
/* the device cell ships both icons; the script adds is-pc / is-mobile
   and this shows the matching one. Both hidden until then - the slot is
   fixed, so nothing moves when the class lands. */
.vc-device .ic-pc,.vc-device .ic-mobile{display:none}
.vc-device.is-pc .ic-pc,.vc-device.is-mobile .ic-mobile{display:block}
.live-dot{position:absolute;top:0;right:0;width:8px;height:8px;border-radius:50%;
  background:#3DBE7A;border:1.5px solid #fff;animation:livePulse 2s ease-in-out infinite}
@keyframes livePulse{0%,100%{opacity:1}50%{opacity:.35}}
.visit-text{min-width:0;line-height:1.25}
.visit-num{display:block;font-family:var(--font-head);font-size:14.5px;font-weight:600;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.visit-label{display:block;font-family:var(--font-head);font-size:10px;letter-spacing:.06em;
  text-transform:uppercase;color:var(--ink-soft)}
@media(max-width:760px){
  /* 2x2 on a phone; still the same reserved cell heights. */
  .visit-strip{grid-template-columns:repeat(2,minmax(0,1fr))}
  .visit-cell{padding:9px 12px}
  .card-body{padding:16px 18px 18px}
  .card-title{font-size:19.5px}
}

b:if.script:
//
(function () {
  function byId(i) { return document.getElementById(i); }
  var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* visits count up once, over 700ms, on rAF - afterwards the page
     holds no animation frame at all. */
  function countUp(el, target) {
    if (!el || !target) { return; }
    if (reduced) { el.textContent = target.toLocaleString('en-US'); return; }
    var t0 = null;
    function step(t) {
      if (!t0) { t0 = t; }
      var p = Math.min((t - t0) / 700, 1);
      el.textContent = Math.round(target * (1 - Math.pow(1 - p, 3))).toLocaleString('en-US');
      if (p < 1) { requestAnimationFrame(step); }
    }
    requestAnimationFrame(step);
  }

  /* device + clock: free, no request at all */
  var cell = document.querySelector('.visit-strip .vc-device');
  var mobile = /Mobi|Android|iPhone|iPad/i.test(navigator.userAgent) ||
    (window.matchMedia && window.matchMedia('(pointer:coarse)').matches);
  if (cell) {
    cell.classList.add(mobile ? 'is-mobile' : 'is-pc');
    byId('visitDevice').textContent = mobile ? 'Mobile' : 'PC';
  }
  function tick() {
    var el = byId('visitTime');
    if (!el) { return; }
    var d = new Date(), h = d.getHours(), m = d.getMinutes(), ap = h < 12 ? 'AM' : 'PM';
    h = h % 12; if (!h) { h = 12; }
    el.textContent = h + ':' + (m < 10 ? '0' + m : m) + ' ' + ap;
  }
  tick();
  setInterval(tick, 1000);

  addEventListener('load', function () {
    var deferFetches = function () {
      (window.requestIdleCallback || function (f) { setTimeout(f, 1000); })(function () {
        /* total visits: Abacus, a free open page-view counter - one
           ~300-byte JSON GET; /hit/ creates the counter on first call,
           no key and no account. Failure leaves the em dash, no retry. */
        fetch('https://abacus.jasoncameron.dev/hit/freestackhub/visits')
          .then(function (r) { return r.json(); })
          .then(function (d) { if (d && d.value) { countUp(byId('visitTotal'), +d.value); } })
          .catch(function () {});

        /* the visitor's own country: ipwho.is free geo lookup - one
           ~500-byte JSON GET. The flag is an emoji built from the ISO
           code: no flag sprite, no image request. */
        fetch('https://ipwho.is/')
          .then(function (r) { return r.json(); })
          .then(function (d) {
            if (!d || !d.success) { return; }
            var name = byId('visitCountry');
            if (name && d.country) { name.textContent = d.country; }
            var code = (d.country_code || '').toUpperCase();
            if (/^[A-Z]{2}$/.test(code) && byId('visitFlag')) {
              byId('visitFlag').textContent = String.fromCodePoint(
                code.charCodeAt(0) + 127397, code.charCodeAt(1) + 127397) + ' ';
            }
          })
          .catch(function () {});
      });
    };
    if ('requestIdleCallback' in window) {
      requestIdleCallback(deferFetches, { timeout: 3500 });
    } else {
      setTimeout(deferFetches, 2500);
    }
  });
})();
//

body.script:
//
(function () {
  var form = document.querySelector('form.search');
  var input = form ? form.querySelector('input[name="q"]') : null;
  var list = document.getElementById('search-suggest');
  if (!form || !input || !list) { return; }

  var POST_ROWS = 7;      // post suggestions, most relevant first
  var LABEL_ROWS = 2;     // ...plus up to two matching labels
  var BROWSE_ROWS = 5;    // newest posts shown when the field is focused empty
  var FEED_MAX = 250;     // posts one request pulls into the index

  var posts = [], labels = [], ready = false, loading = false;
  var rows = [], active = -1;

  /* The feed is on this blog's own origin. The form's action is
     <homepageUrl>search, so the homepage - and the feed under it - is that
     minus its trailing "search". Nothing per-blog to configure, no
     cross-origin request. */
  var home = (form.getAttribute('action') || '').replace(/search\/?$/, '');
  var FEED = home + 'feeds/posts/summary?alt=json&max-results=' + FEED_MAX;
  /* theme/preview.html injects a sample index instead of fetching: a mock on
     disk has no feed to ask. Absent on Blogger. */
  var SAMPLE = window.FSH_SEARCH_SAMPLE;

  function norm(s) { return String(s === null || s === undefined ? '' : s).toLowerCase(); }
  function tokens(s) { return norm(s).split(/[^a-z0-9\u00c0-\u024f]+/).filter(Boolean); }
  function isOpen() { return list.className.indexOf('is-open') !== -1; }

  /* ---------------- the index ---------------- */

  function meta(p) { return p.l.length ? p.l.slice(0, 3).join(' · ') : (p.d || 'Post'); }

  function ingest(raw) {
    var i, j, p, seen = {}, found = [];
    posts = [];
    for (i = 0; i < raw.length; i++) {
      p = raw[i];
      if (!p || !p.t || !p.u) { continue; }
      p.l = p.l || [];
      /* Lowercase haystack + word list are built ONCE per post, not once per
         keystroke - typing then costs a couple of indexOf calls per row. */
      p.h = norm(p.t) + ' ' + norm(p.l.join(' '));
      p.w = tokens(p.t + ' ' + p.l.join(' '));
      posts.push(p);
      for (j = 0; j < p.l.length; j++) {
        if (!seen[p.l[j]]) { seen[p.l[j]] = 1; found.push(p.l[j]); }
      }
    }
    labels = found.sort(function (a, b) { return norm(a) < norm(b) ? -1 : 1; });
    ready = true;
    loading = false;
    /* the visitor may already have typed while the feed was in flight */
    if (document.activeElement === input) { render(); }
  }

  function ensureIndex() {
    if (ready || loading) { return; }
    loading = true;
    if (SAMPLE && SAMPLE.length) { ingest(SAMPLE); return; }
    if (!window.fetch) { loading = false; return; }   // stays a plain search form
    fetch(FEED)
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (d) {
        var entries = (d && d.feed && d.feed.entry) || [], out = [], i, j, e, links, cats, href, labs;
        for (i = 0; i < entries.length; i++) {
          e = entries[i]; links = e.link || []; cats = e.category || []; href = ''; labs = [];
          for (j = 0; j < links.length; j++) {
            if (links[j].rel === 'alternate' && links[j].href) { href = links[j].href; break; }
          }
          for (j = 0; j < cats.length; j++) { if (cats[j].term) { labs.push(cats[j].term); } }
          out.push({
            t: (e.title && e.title.$t) || '',
            u: href,
            l: labs,
            d: ((e.published && e.published.$t) || '').slice(0, 10)
          });
        }
        ingest(out);
      })
      .catch(function () { ready = true; loading = false; });
  }

  /* ---------------- matching: every word typed has to be in the row ---- */

  function score(post, qs, q) {
    var s = 0, i, j, hit;
    for (i = 0; i < qs.length; i++) {
      hit = 0;
      for (j = 0; j < post.w.length; j++) {
        if (post.w[j].indexOf(qs[i]) === 0) { hit = 4; break; }   // a word starts with it
      }
      if (!hit && post.h.indexOf(qs[i]) !== -1) { hit = 2; }      // ...or it is inside one
      if (!hit) { return -1; }                                    // word absent: the row is out
      s += hit;
    }
    if (norm(post.t).indexOf(q) === 0) { s += 8; }                // title starts with the phrase
    else if (post.h.indexOf(q) !== -1) { s += 3; }
    return s;
  }

  function match(q) {
    var qs = tokens(q), found = [], outPosts = [], outLabels = [], i, j, k, s, lw, keep;
    q = q.replace(/\s+/g, ' ').trim();
    if (!qs.length) { return { posts: [], labels: [], q: '' }; }
    for (i = 0; i < posts.length; i++) {
      s = score(posts[i], qs, q);
      if (s >= 0) { found.push({ i: i, s: s }); }
    }
    /* relevance first; a tie keeps the feed's own newest-first order */
    found.sort(function (a, b) { return b.s - a.s || a.i - b.i; });
    for (i = 0; i < found.length && outPosts.length < POST_ROWS; i++) { outPosts.push(posts[found[i].i]); }
    /* Labels obey the same rule as posts: EVERY word typed has to be in the
       label, a word start first and a substring as the fallback ("git hub"
       still finds the GitHub label, "python zzz" finds nothing). Otherwise a
       label row survives a word that ruled every post out, and the list looks
       like it ignored what was just typed. */
    for (i = 0; i < labels.length && outLabels.length < LABEL_ROWS; i++) {
      lw = tokens(labels[i]);
      keep = true;
      for (k = 0; k < qs.length && keep; k++) {
        keep = false;
        for (j = 0; j < lw.length; j++) {
          if (lw[j].indexOf(qs[k]) === 0) { keep = true; break; }
        }
        if (!keep && norm(labels[i]).indexOf(qs[k]) !== -1) { keep = true; }
      }
      if (keep) { outLabels.push(labels[i]); }
    }
    return { posts: outPosts, labels: outLabels, q: q };
  }

  /* ---------------- rendering ---------------- */

  /* Text is written with createTextNode / textContent only: a post title is
     content, never markup, so nothing that comes back in the feed can inject
     a tag. The typed words are highlighted by splitting the text into nodes
     and wrapping the matching slices in <mark>. */
  function markUp(el, text, q) {
    var qs = tokens(q), lower = norm(text), hits = [], i, j, pos = 0, mk;
    for (i = 0; i < qs.length; i++) {
      j = lower.indexOf(qs[i]);
      while (j !== -1) { hits.push([j, j + qs[i].length]); j = lower.indexOf(qs[i], j + qs[i].length); }
    }
    if (!hits.length) { el.textContent = text; return; }
    hits.sort(function (a, b) { return a[0] - b[0] || b[1] - a[1]; });
    for (i = 0; i < hits.length; i++) {
      if (hits[i][0] < pos) { continue; }                          // overlaps a marked slice
      if (hits[i][0] > pos) { el.appendChild(document.createTextNode(text.slice(pos, hits[i][0]))); }
      mk = document.createElement('mark');
      mk.textContent = text.slice(hits[i][0], hits[i][1]);
      el.appendChild(mk);
      pos = hits[i][1];
    }
    if (pos < text.length) { el.appendChild(document.createTextNode(text.slice(pos))); }
  }

  function addRow(kind, item, q) {
    var li = document.createElement('li');
    li.id = 'search-sg-' + rows.length;
    li.className = 'sg-' + kind;
    li.setAttribute('role', 'option');
    li.setAttribute('aria-selected', 'false');
    var a = document.createElement('a');
    a.href = item.u;
    a.tabIndex = -1;                        // walked with the arrow keys, not with Tab
    var t = document.createElement('span');
    t.className = 'sg-title';
    markUp(t, item.t, q);
    a.appendChild(t);
    if (item.m) {
      var m = document.createElement('span');
      m.className = 'sg-meta';
      m.textContent = item.m;
      a.appendChild(m);
    }
    li.appendChild(a);
    list.appendChild(li);
    rows.push(li);
  }

  function render() {
    var res = match(input.value), i;
    rows = [];
    active = -1;
    input.removeAttribute('aria-activedescendant');
    while (list.firstChild) { list.removeChild(list.firstChild); }

    if (!res.q) {
      /* focused but empty: the newest posts, so the list is not a dead end
         before anyone has typed anything */
      for (i = 0; i < posts.length && rows.length < BROWSE_ROWS; i++) {
        addRow('post', { t: posts[i].t, u: posts[i].u, m: meta(posts[i]) }, '');
      }
      if (rows.length) { open(); } else { close(); }
      return;
    }

    for (i = 0; i < res.posts.length; i++) {
      addRow('post', { t: res.posts[i].t, u: res.posts[i].u, m: meta(res.posts[i]) }, res.q);
    }
    for (i = 0; i < res.labels.length; i++) {
      addRow('label', {
        t: res.labels[i],
        u: home + 'search/label/' + encodeURIComponent(res.labels[i]),
        m: 'Category · every post filed under it'
      }, res.q);
    }
    /* The last row is always Blogger's own results page for the phrase, so a
       query that matches no title still has somewhere to go - and the
       listbox always holds at least one option, which is what its role
       requires. The wording differs on purpose: "no title matches" is only
       true when a title list actually arrived. With no index at all (feed
       blocked, offline, nothing published yet) the row just says what it
       does, instead of claiming to have searched titles it never had. */
    var hits = res.posts.length + res.labels.length;
    addRow('all', {
      t: hits ? 'See every result for “' + res.q + '”'
              : (posts.length ? 'No title matches “' + res.q + '” — search the whole blog'
                              : 'Search the blog for “' + res.q + '”'),
      u: home + 'search?q=' + encodeURIComponent(res.q),
      m: hits ? '' : (posts.length ? 'Blogger search, not only these titles' : 'Blogger search')
    }, '');
    open();
  }

  /* ---------------- open / close / the keyboard row ---------------- */

  function open() {
    if (isOpen()) { return; }
    list.className += ' is-open';
    input.setAttribute('aria-expanded', 'true');
  }

  function close() {
    list.className = list.className.replace(/\s*is-open/, '');
    input.setAttribute('aria-expanded', 'false');
    input.removeAttribute('aria-activedescendant');
    for (var i = 0; i < rows.length; i++) {
      rows[i].className = rows[i].className.replace(/\s*is-active/, '');
      rows[i].setAttribute('aria-selected', 'false');
    }
    active = -1;
  }

  function setActive(i) {
    if (!rows.length) { return; }
    if (i < 0) { i = rows.length - 1; }              // wraps both ways
    if (i > rows.length - 1) { i = 0; }
    for (var k = 0; k < rows.length; k++) {
      rows[k].className = rows[k].className.replace(/\s*is-active/, '');
      rows[k].setAttribute('aria-selected', k === i ? 'true' : 'false');
    }
    rows[i].className += ' is-active';
    active = i;
    input.setAttribute('aria-activedescendant', rows[i].id);
    /* Keep the active row inside the panel's own scroll box. Done by hand:
       scrollIntoView can scroll the PAGE as well on some browsers, which
       would move the field out from under the visitor. */
    var top = rows[i].offsetTop, bottom = top + rows[i].offsetHeight;
    if (top < list.scrollTop) { list.scrollTop = top; }
    else if (bottom > list.scrollTop + list.clientHeight) { list.scrollTop = bottom - list.clientHeight; }
  }

  /* ---------------- events ---------------- */

  input.addEventListener('focus', function () { ensureIndex(); if (ready) { render(); } });
  input.addEventListener('input', function () { ensureIndex(); if (ready) { render(); } });

  input.addEventListener('keydown', function (e) {
    var k = e.key, a;
    if (k === 'ArrowDown' || k === 'Down') {
      e.preventDefault();
      if (!isOpen() && ready) { render(); }
      if (isOpen()) { setActive(active + 1); }
    } else if (k === 'ArrowUp' || k === 'Up') {
      /* Either arrow opens a closed list: after an Escape, or on a field the
         visitor reached with the keyboard, the first arrow press should show
         the suggestions rather than do nothing at all. */
      e.preventDefault();
      if (!isOpen() && ready) { render(); }
      if (isOpen()) { setActive(active - 1); }
    } else if (k === 'Enter') {
      /* A row you are standing on wins over the form: Enter opens it. With no
         row active the form submits, which is Blogger's own results page for
         whatever is typed - the behaviour the field always had. */
      if (isOpen() && active > -1 && rows[active]) {
        a = rows[active].firstChild;
        if (a && a.href) { e.preventDefault(); window.location.href = a.href; }
      }
      close();
    } else if (k === 'Escape' || k === 'Esc' || k === 'Tab') {
      close();
    }
  });

  /* A click on a row must not be swallowed by the field's blur, and focus
     stays on the combobox: stop the mousedown, let the click reach the link. */
  list.addEventListener('mousedown', function (e) { e.preventDefault(); });
  list.addEventListener('click', close);
  list.addEventListener('mouseover', function (e) {
    var li = e.target, i;
    while (li && li !== list && (!li.getAttribute || li.getAttribute('role') !== 'option')) { li = li.parentNode; }
    if (li && li !== list) { i = rows.indexOf(li); if (i > -1 && i !== active) { setActive(i); } }
  });
  input.addEventListener('blur', function () { window.setTimeout(close, 120); });
})();
//
